+#[cfg(test)]
+mod persistence_revision_tests {
+    use super::*;
+
+    #[test]
+    fn legacy_revision_defaults_and_successful_saves_advance_exactly_once() {
+        let model = ocean_protocol::Model::anthropic_claude_sonnet_4_6();
+        let legacy = serde_json::json!({
+            "id": SessionId::new_v4(),
+            "created_ms": 1,
+            "updated_ms": 1,
+            "model": model.id,
+            "provider": model.provider,
+            "messages": []
+        });
+        let decoded: Session = serde_json::from_value(legacy).unwrap();
+        assert_eq!(decoded.persistence_revision, 0);
+
+        let dir = tempfile::tempdir().unwrap();
+        let mut session = decoded;
+        let fixed_updated = session.updated_ms;
+        save(dir.path(), &mut session).unwrap();
+        assert_eq!(session.persistence_revision, 1);
+        session.updated_ms = fixed_updated;
+        save(dir.path(), &mut session).unwrap();
+        assert_eq!(session.persistence_revision, 2);
+        assert_eq!(
+            load(dir.path(), session.id).unwrap().persistence_revision,
+            2
+        );
+    }
+
+    #[test]
+    fn failed_save_changes_neither_candidate_nor_last_good_disk_revision() {
+        let model = ocean_protocol::Model::anthropic_claude_sonnet_4_6();
+        let dir = tempfile::tempdir().unwrap();
+        let mut session = Session::new(&model);
+        save(dir.path(), &mut session).unwrap();
+        assert_eq!(session.persistence_revision, 1);
+
+        session.persistence_revision = u64::MAX;
+        assert!(save(dir.path(), &mut session).is_err());
+        assert_eq!(session.persistence_revision, u64::MAX);
+        assert_eq!(
+            load(dir.path(), session.id).unwrap().persistence_revision,
+            1
+        );
+    }
+}
