+async fn session_projection_events(
+    State(state): State<AppState>,
+    Query(query): Query<SessionProjectionEventsQuery>,
+) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
+    let (tx, rx) = mpsc::channel(64);
+    let shutdown = state.shutdown.clone();
+    let session_id = query.session_id.to_string();
+    let mut cursor = query.after_cursor;
+    let projection = state.agent_events.projection();
+
+    tokio::spawn(async move {
+        let Some(store) = projection else {
+            let data = json!({ "type": "projection_reset", "reason": "projection_unavailable" })
+                .to_string();
+            let _ = tx
+                .send(Ok(Event::default().event("projection_reset").data(data)))
+                .await;
+            return;
+        };
+
+        // Register before the first durable page. Any append racing the query is
+        // either visible in SQLite or leaves a buffered wake that causes re-page.
+        let mut wakes = store.subscribe();
+        loop {
+            match store.page_after(&session_id, &cursor) {
+                Ok(frames) if !frames.is_empty() => {
+                    for frame in frames {
+                        cursor = frame.cursor.clone();
+                        let data = serde_json::to_string(&frame).unwrap_or_else(|_| {
+                            json!({ "type": "projection_reset", "reason": "serialize_failed" })
+                                .to_string()
+                        });
+                        if tx
+                            .send(Ok(Event::default()
