+                        }
+                    }
+                    continue;
+                }
+                Ok(_) => {}
+                Err(reset) => {
+                    let data = json!({
+                        "type": "projection_reset",
+                        "reason": reset.reason(),
+                    })
+                    .to_string();
+                    let _ = tx
+                        .send(Ok(Event::default().event("projection_reset").data(data)))
+                        .await;
+                    return;
+                }
+            }
+
+            tokio::select! {
+                _ = shutdown.cancelled() => return,
+                _ = tx.closed() => return,
