+            .page_after(&session.to_string(), &snapshot.cursor)
+            .unwrap();
+        assert_eq!(page.len(), 1);
+        assert_eq!(page[0].event["delta"], "after snapshot");
+    }
+
+    #[test]
+    fn daemon_restart_changes_epoch_and_clears_transient_fold() {
+        let dir = tempdir().unwrap();
+        let path = dir.path().join("projection.db");
+        let session = AgentSessionId::new_v4();
+        let turn = AgentTurnId::new_v4();
+        let first =
+            SessionProjectionStore::open_with_config(&path, 1024 * 1024, DEFAULT_LEASE).unwrap();
+        first
+            .append_agent(&AgentTurnEvent::ThinkingDelta {
+                session_id: session,
+                turn_id: turn,
+                delta: "transient".into(),
+            })
+            .unwrap();
+        let old = first.snapshot(&session.to_string(), 7).unwrap();
+        drop(first);
+
+        let second =
+            SessionProjectionStore::open_with_config(&path, 1024 * 1024, DEFAULT_LEASE).unwrap();
+        assert_eq!(
+            second
+                .page_after(&session.to_string(), &old.cursor)
+                .unwrap_err(),
+            ProjectionReset::WrongEpoch
+        );
+        let fresh = second.snapshot(&session.to_string(), 7).unwrap();
+        assert!(fresh.pending_events.is_empty());
+        assert!(fresh.state.active_turn.is_none());
+        assert_eq!(fresh.checkpoint_revision, 7);
+    }
+
+    #[test]
+    fn active_attach_lease_protects_checkpointed_catchup_under_pressure() {
+        let dir = tempdir().unwrap();
+        let store = SessionProjectionStore::open_with_config(
+            &dir.path().join("projection.db"),
+            1,
+            DEFAULT_LEASE,
+        )
+        .unwrap();
+        let session = AgentSessionId::new_v4();
+        let turn = AgentTurnId::new_v4();
+        let attached = store.snapshot(&session.to_string(), 0).unwrap();
+        store
+            .append_agent(&AgentTurnEvent::AssistantTextDelta {
+                session_id: session,
+                turn_id: turn,
+                delta: "must survive".into(),
+            })
+            .unwrap();
+        store.checkpoint(&session.to_string(), 1).unwrap();
+        let page = store
+            .page_after(&session.to_string(), &attached.cursor)
+            .unwrap();
+        assert_eq!(page.len(), 1);
+    }
+
+    #[test]
+    fn checkpoint_compacts_only_committed_rows_after_lease_expiry() {
+        let store = store(Duration::ZERO);
+        let session = AgentSessionId::new_v4();
+        let turn = AgentTurnId::new_v4();
+        store
+            .append_agent(&AgentTurnEvent::AssistantTextDelta {
+                session_id: session,
+                turn_id: turn,
+                delta: "done".into(),
+            })
+            .unwrap();
+        store.checkpoint(&session.to_string(), 1).unwrap();
+        store.compact(false).unwrap();
+        let snapshot = store.snapshot(&session.to_string(), 1).unwrap();
+        assert!(snapshot.pending_events.is_empty());
+        let old = ProjectionCursor::new(&store.epoch, &session.to_string(), 0).to_string();
+        assert_eq!(
+            store.page_after(&session.to_string(), &old).unwrap_err(),
+            ProjectionReset::Retention
+        );
+    }
+}

