    // the daemon/SDK can route by session natively instead of re-attaching it.
    let sid = config.session_id.clone();

    if let Some(last) = messages.last().cloned() {
        emit(
            &events,
            AgentEvent::UserMessage {
                session_id: sid.clone(),
                message: last,
            },
        );
    }
