    let mut session_allowed: HashSet<String> = HashSet::new();
    let mut turn: u32 = 0;
    let mut stopped_at_turn_limit = false;
    let mut total_usage = ocean_protocol::Usage::default();
    let mut latest_context_tokens = 0;
