            outcomes.resize_with(segment.len(), || None);
            let mut segment_cancelled = false;
            loop {
                let next = tokio::select! {
                    biased;
                    () = cancelled(config) => {
                        segment_cancelled = true;
                        break;
                    },
                    next = futures::StreamExt::next(&mut in_flight) => next,
                };
